import sys

def calc_brute(equations, queries):
    graph = {}
    for (u, v), w in equations:
        graph.setdefault(u, []).append((v, w))
        graph.setdefault(v, []).append((u, 1.0 / w))

    def dfs(u, v, acc, visited):
        if u == v:
            return acc
        visited.add(u)
        for nxt, w in graph.get(u, []):
            if nxt not in visited:
                r = dfs(nxt, v, acc * w, visited)
                if r != -1.0:
                    return r
        return -1.0

    res = []
    for u, v in queries:
        if u == v and u in graph:
            res.append(1.0)
        elif u in graph:
            res.append(dfs(u, v, 1.0, set()))
        else:
            res.append(-1.0)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    e = int(data[0])
    idx = 1
    eqs = []
    for _ in range(e):
        a, b = data[idx], data[idx + 1]
        w = float(data[idx + 2])
        eqs.append(((a, b), w))
        idx += 3
    q = int(data[idx]); idx += 1
    qs = []
    for _ in range(q):
        qs.append((data[idx], data[idx + 1]))
        idx += 2
    for r in calc_brute(eqs, qs):
        print('%.1f' % r)

import sys
from collections import deque

def calc_opt(equations, queries):
    graph = {}
    for (u, v), w in equations:
        graph.setdefault(u, []).append((v, w))
        graph.setdefault(v, []).append((u, 1.0 / w))

    def bfs(u, v):
        if u not in graph or v not in graph:
            return -1.0
        if u == v:
            return 1.0
        q = deque([(u, 1.0)])
        seen = {u}
        while q:
            cur, acc = q.popleft()
            if cur == v:
                return acc
            for nxt, w in graph.get(cur, []):
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, acc * w))
        return -1.0

    return [bfs(u, v) for u, v in queries]

