import sys

def calc_best(equations, queries):
    nodes = []
    graph = {}
    for (u, v), w in equations:
        graph.setdefault(u, {})[v] = w
        graph.setdefault(v, {})[u] = 1.0 / w
        if u not in nodes: nodes.append(u)
        if v not in nodes: nodes.append(v)

    dist = {a: {b: 0.0 for b in nodes} for a in nodes}
    for a in nodes:
        dist[a][a] = 1.0
    for a in nodes:
        for b, w in graph[a].items():
            dist[a][b] = w

    for k in nodes:
        for i in nodes:
            for j in nodes:
                if dist[i][k] and dist[k][j]:
                    cand = dist[i][k] * dist[k][j]
                    if dist[i][j] == 0.0:
                        dist[i][j] = cand

    res = []
    for u, v in queries:
        if u in dist and v in dist and dist[u][v] != 0.0:
            res.append(dist[u][v])
        else:
            res.append(-1.0)
    return res

